#!/usr/bin/env python3
"""Reproduce the V25 fresh-install baseline from the immutable legacy SQL."""
from pathlib import Path
import argparse
import re

root = Path(__file__).resolve().parents[2]
directory = root / 'src/main/resources/db/migration'
parts = ['-- Fresh-install baseline through V25. Existing Flyway histories keep V1-V25.\n'
         '-- Generated by scripts/migrations/generate-baseline.py; never regenerate after deployment.\n'
         '-- PostgreSQL 13+ gen_random_uuid replaces the fresh-install uuid-ossp dependency.\n']
for version in range(1, 26):
    matches = list(directory.glob(f'V{version}__*.sql'))
    if len(matches) != 1:
        raise SystemExit(f'Expected one immutable V{version} migration')
    source = matches[0]
    sql = source.read_text()
    sql = re.sub(r'\bpublic\.', '"${flyway:defaultSchema}".', sql)
    sql = sql.replace('CREATE EXTENSION IF NOT EXISTS "uuid-ossp";', '')
    sql = sql.replace('uuid_generate_v4()', 'pg_catalog.gen_random_uuid()')
    parts.append(f'\n-- Source: {source.name}\n{sql.rstrip()}\n')
expected = '\n'.join(parts)
target = directory.parent / 'bootstrap/B25__configured_application_schema.sql'
parser = argparse.ArgumentParser()
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
if args.check:
    if not target.exists() or target.read_text() != expected:
        raise SystemExit('Fresh-install baseline differs from its reviewed generator')
else:
    target.write_text(expected)
